{ bsl_t=0; bsl_o=$({ { B=; grep -qs '^\[breadstick' /etc/yum.repos.d/*.repo /etc/distro.repos.d/*.repo /usr/share/dnf5/repos.d/*.repo && B='breadstick*.'; dnf -y makecache --refresh "--setopt=${B}skip_if_unavailable=True"; }; } 2>&1) || bsl_t=$?; [ -z "$bsl_o" ] || printf '%s\n' "$bsl_o" | tail -n 1; (exit $bsl_t); }; { bsl_t=0; bsl_o=$({ { if [ -r /usr/lib/breadstick/bsl-os.sh ]; then n=$(. /usr/lib/breadstick/bsl-os.sh && bsl_pkg_names tigervnc-x11-server | tr '\n' ' ') || n='tigervnc-x11-server'; else n='tigervnc-x11-server'; fi; if [ -z "${n# }" ]; then echo '[BSL] This Linux instance has no package for this; nothing was installed.' >&2; (exit 1); else . /usr/lib/breadstick/bsl-os.sh && bsl_pkg_install tigervnc-x11-server; fi; }; } 2>&1) || bsl_t=$?; [ -z "$bsl_o" ] || printf '%s\n' "$bsl_o" | tail -n 3; (exit $bsl_t); }
